    MEDIUM = true,
    HIGH = true,
    DIALOG = true,
    FULLSCREEN = true,
    FULLSCREEN_DIALOG = true,
    TOOLTIP = true,
}
local function NormalizeOakFrameStrata(strata)
    local normalized = tostring(strata or ""):upper()
    if VALID_FRAME_STRATA[normalized] then
        return normalized
    end
    return "DIALOG"
end

